mod solution;use solution::circuit_trace;#[test]fn contract(){assert_eq!(circuit_trace("2;FSFFS"),Some("CCCOO".to_string()));
assert_eq!(circuit_trace("1;SFS"),Some("COO".to_string()));
assert_eq!(circuit_trace("2147483647;"),Some("".to_string()));
assert_eq!(circuit_trace("0;F"),None);
assert_eq!(circuit_trace("+2;FF"),None);
assert_eq!(circuit_trace("02;FF"),None);
assert_eq!(circuit_trace("2147483648;F"),None);
assert_eq!(circuit_trace("2;FX"),None);}
